using System;using System.Drawing;using System.Reflection;using System.Windows.Forms;using LoopFive;
class UiTests {
 static int checks;static void A(bool c,string text){if(!c)throw new Exception(text);Console.WriteLine("PASS "+text);checks++;}
 static object Field(object target,string name){return target.GetType().GetField(name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(target);}
 static void Mouse(Control control,int x,int y,bool down){typeof(Control).GetMethod(down?"OnMouseDown":"OnMouseUp",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(control,new object[]{new MouseEventArgs(MouseButtons.Left,1,x,y,0)});}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{using(MainForm f=new MainForm()){f.Opacity=0;f.Show();Application.DoEvents();((System.Windows.Forms.Timer)Field(f,"timer")).Stop();f.Audio.Stop();f.Engine.Config.Quantize=false;f.Engine.Tracks[0].Config.LoopSync=false;TrackStrip[] strips=(TrackStrip[])Field(f,"strips");Mouse(strips[0],strips[0].Width/2,strips[0].Height-145,true);A(f.Engine.Tracks[0].State==PlayState.Recording,"track circle starts recording");((Button)Field(strips[0],"stop")).PerformClick();A(f.Engine.Tracks[0].State==PlayState.Empty,"track stop button connected");FxBar bar=(FxBar)Field(f,"inputBar");Button[] slots=(Button[])Field(bar,"slots");Mouse(slots[1],10,10,true);A(f.Engine.Config.InputFx.Slots[1].On,"FX button activates correct slot");f.Engine.Config.InputFx.Slots[1].Momentary=true;Mouse(slots[1],10,10,false);A(!f.Engine.Config.InputFx.Slots[1].On,"FX mouse release ends momentary effect");
 RhythmPage rp=(RhythmPage)Field(f,"rhythmPage");f.Engine.Config.Rhythm.StartMode=2;f.Engine.Config.Rhythm.StopMode=2;f.Engine.Config.Rhythm.Intro=true;rp.RefreshModel();A(((ComboBox)Field(rp,"startMode")).SelectedIndex==2&&((ComboBox)Field(rp,"stopMode")).SelectedIndex==2&&((CheckBox)Field(rp,"intro")).Checked,"loaded rhythm controls reflect saved values");
 FxPage fp=(FxPage)Field(f,"fxPage");fp.SelectSlot(false,2,1);Panel scroll=(Panel)Field(fp,"scroll");EditorGrid grid=(EditorGrid)scroll.Controls[0];ComboBox type=(ComboBox)grid.GetControlFromPosition(1,1);type.SelectedIndex=Array.IndexOf(FxCatalog.All,"DIST");A(f.Engine.Config.TrackFx.Slots[9].Type=="DIST"&&f.Engine.Config.InputFx.Slots[9].Type!="DIST","FX editor edits selected bank/section");
 Snapshot demo=Demo.Create();Storage.Apply(f.Engine,demo);f.RefreshModel();A(((NumericUpDown)Field(f,"bpm")).Value==100&&((TextBox)Field(f,"sessionName")).Text==demo.Config.Name,"session load refreshes header controls");f.Engine.Config.TrackFx.Slots[0].Type="LPF";f.Engine.Tracks[0].Config.LoopSync=false;f.Engine.Config.Quantize=false;Mouse(strips[0],strips[0].Width/2,strips[0].Height-145,true);A(f.Engine.Tracks[0].Playing,"track controls remain connected after session replacement");f.Engine.Dirty=false;f.Close();}Console.WriteLine("TOTAL "+checks+" UI interaction checks passed");}catch(Exception e){Console.WriteLine("FAIL "+e);Environment.ExitCode=1;}}
}
